package org.sakaiproject.util;

import org.sakaiproject.thread_local.api.ThreadLocalManager;
import org.sakaiproject.component.cover.ComponentManager;
import javax.servlet.*;
import java.io.IOException;

public class ThreadLocalCleanupFilter implements Filter {
    private static final String[] KEYS = {
        RequestFilter.CURRENT_HTTP_REQUEST,
        RequestFilter.CURRENT_HTTP_RESPONSE,
        RequestFilter.CURRENT_SERVLET_CONTEXT,
        RequestFilter.CURRENT_REMOTE_USER,
        RequestFilter.CURRENT_HTTP_SESSION,
        RequestFilter.CURRENT_CONTEXT
    };

    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        ThreadLocalManager tlm = ComponentManager.get(ThreadLocalManager.class);
        try {
            chain.doFilter(req, res);
        } finally {
            for (String key : KEYS) {
                try {
                    tlm.remove(key);
                } catch (Exception e) {
                    // log and continue — cleanup must not throw
                }
            }
        }
    }

    @Override public void init(FilterConfig cfg) {}
    @Override public void destroy() {}
}

package org.sakaiproject.util;

public enum SessionMode {
    CONTAINER,
    SAKAI,
    CONTEXT,
    TOOL;

    public static SessionMode fromInt(int value) {
        switch (value) {
            case 0: return CONTAINER;
            case 1: return SAKAI;
            case 2: return CONTEXT;
            case 3: return TOOL;
            default: throw new IllegalArgumentException("Unknown session mode: " + value);
        }
    }

    public int toInt() {
        return ordinal();
    }
}

package org.sakaiproject.util;

import org.sakaiproject.cluster.api.ClusterService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ClusterServiceGuard {
    private static final Logger log = LoggerFactory.getLogger(ClusterServiceGuard.class);
    private static final long TIMEOUT_MS = 2000;
    private static final int FAILURE_THRESHOLD = 5;
    private static final long OPEN_MS = 30000;

    private final ClusterService clusterService;
    private final ExecutorService executor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "cluster-guard");
        t.setDaemon(true);
        return t;
    });
    private final AtomicInteger failures = new AtomicInteger(0);
    private volatile long openUntil = 0;

    public ClusterServiceGuard(ClusterService clusterService) {
        this.clusterService = clusterService;
    }

    public ClusterService.Status getStatus() {
        if (System.currentTimeMillis() < openUntil) {
            log.warn("ClusterService circuit OPEN — returning null status");
            return null;
        }
        try {
            Future<ClusterService.Status> f = executor.submit(clusterService::getStatus);
            ClusterService.Status s = f.get(TIMEOUT_MS, TimeUnit.MILLISECONDS);
            failures.set(0);
            return s;
        } catch (Exception e) {
            int n = failures.incrementAndGet();
            log.warn("ClusterService call failed ({}): {}", n, e.toString());
            if (n >= FAILURE_THRESHOLD) {
                openUntil = System.currentTimeMillis() + OPEN_MS;
                log.error("ClusterService circuit OPEN for {}ms", OPEN_MS);
            }
            return null;
        }
    }
}
